(7705245, 1265266, 59737, '<td valign="top">nice find, like the layers of stacked books works really well for the challenge</td>', 'nice find, like the layers of stacked books works really well for the challenge', '2021-11-01 12:00:38.000000', NULL, 1),
(7705246, 1265328, 59737, '<td valign="top">very clean nice image, like how all the brown colors work together and the repeating shapes of the stacked items</td>', 'very clean nice image, like how all the brown colors work together and the repeating shapes of the stacked items', '2021-11-01 12:01:12.000000', NULL, 1),
(7705247, 1265302, 59737, '<td valign="top">seems kind of dark for a reading corner, but I like the moodiness of the image</td>', 'seems kind of dark for a reading corner, but I like the moodiness of the image', '2021-11-01 12:01:53.000000', NULL, 1),
(7705299, 1265328, 3306, '<td valign="top">This has potential to be a very interesting composition. The subject matter and brown tones are appealing. There are several issues I would like to suggest in editing to make it even better. The most important issue I see is the parallelism which can be corrected using the transform tool if you have photoshop. Secondly, the lighting is uneven and the glare on the cups is distracting. Thirdly, I would recommend  taking the picture from a more horizontal direction to the midline of the cupboard. It would have given a better perspective and allowed you to capture the top of the cupboard in the photograph. This is not an easy shot to get right.  I hope this helps. 6</td>', 'This has potential to be a very interesting composition. The subject matter and brown tones are appealing. There are several issues I would like to suggest in editing to make it even better. The most important issue I see is the parallelism which can be corrected using the transform tool if you have photoshop. Secondly, the lighting is uneven and the glare on the cups is distracting. Thirdly, I would recommend  taking the picture from a more horizontal direction to the midline of the cupboard. It would have given a better perspective and allowed you to capture the top of the cupboard in the photograph. This is not an easy shot to get right.  I hope this helps. 6', '2021-11-01 19:38:31.000000', NULL, 1),
(7705300, 1265357, 3306, '<td valign="top">A different way of thinking about "Stacks". I like your thinking outside the box!</td>', 'A different way of thinking about "Stacks". I like your thinking outside the box!', '2021-11-01 19:39:39.000000', NULL, 1),
(7705305, 1265357, 59737, '<td valign="top">great colors and light, like the processing choices you made on this</td>', 'great colors and light, like the processing choices you made on this', '2021-11-01 22:06:04.000000', NULL, 1),
(7705306, 1265353, 59737, '<td valign="top">clean image that should do well, the eggs not appearing fully aligned up is throwing me, like the lighting and processing on this</td>', 'clean image that should do well, the eggs not appearing fully aligned up is throwing me, like the lighting and processing on this', '2021-11-01 22:07:22.000000', NULL, 1),
(7705419, 1265340, 3306, '<td valign="top">I like this a lot. Especially the single cardinal by himself. Great capture and I like the soft processing.</td>', 'I like this a lot. Especially the single cardinal by himself. Great capture and I like the soft processing.', '2021-11-02 22:54:21.000000', NULL, 1),
(7705420, 1265353, 3306, '<td valign="top">Excellent take on the challenge. Well done photographically. Very creative. Should ribbon.</td>', 'Excellent take on the challenge. Well done photographically. Very creative. Should ribbon.', '2021-11-02 22:55:54.000000', NULL, 1),
(7705421, 1265358, 3306, '<td valign="top">My favorite of the challenge. I really like the way you have taken the challenge description and built a story around it. Its not just a stack of things. Terrific model and I love the perspective.</td>', 'My favorite of the challenge. I really like the way you have taken the challenge description and built a story around it. Its not just a stack of things. Terrific model and I love the perspective.', '2021-11-02 22:59:30.000000', NULL, 1),
