(7705605, 1265266, 67258, '<td valign="top">I will hazard an English second hand book shop.  Certainly I have been in others like this - really well captured, with the peek into the next room.</td>', 'I will hazard an English second hand book shop.  Certainly I have been in others like this - really well captured, with the peek into the next room.', '2021-11-03 14:48:20.000000', NULL, 1),
(7705606, 1265328, 67258, '<td valign="top">What a superb display of this pottery.  For me the image would be strengthened with some perspective correction, but I do like it regardless.</td>', 'What a superb display of this pottery.  For me the image would be strengthened with some perspective correction, but I do like it regardless.', '2021-11-03 14:49:34.000000', NULL, 1),
(7705607, 1265278, 67258, '<td valign="top">An interesting use of an ''arty'' filter, which has the effect of slightly sanitising the plates (no bad thing as left overs never look appealing).  Works well for the challenge.</td>', 'An interesting use of an ''arty'' filter, which has the effect of slightly sanitising the plates (no bad thing as left overs never look appealing).  Works well for the challenge.', '2021-11-03 14:50:42.000000', NULL, 1),
(7705609, 1265332, 67258, '<td valign="top">I wonder, has this been blurred in post processing rather than through depth of field control in capture?  There appears to be a bit of the t-shirt, between the two bricks, that is sharp.  Once seen, it throws the photo off.</td>', 'I wonder, has this been blurred in post processing rather than through depth of field control in capture?  There appears to be a bit of the t-shirt, between the two bricks, that is sharp.  Once seen, it throws the photo off.', '2021-11-03 14:52:53.000000', NULL, 1),
